-- 42 "norme" support: detection, norminette for nvim-lint, editor settings.
local M = {}

-- Second line of the header generated by :Stdheader.
local header_marker = ":::      ::::::::"

local function resolve(bufnr)
  if not bufnr or bufnr == 0 then
    return vim.api.nvim_get_current_buf()
  end
  return bufnr
end

function M.has_header(bufnr)
  for _, line in ipairs(vim.api.nvim_buf_get_lines(resolve(bufnr), 0, 12, false)) do
    if line:find(header_marker, 1, true) then
      return true
    end
  end
  return false
end

-- Project markers: an empty `.norm42` forces the norm for the whole tree
-- below it, `.nonorm42` disables it. Set vim.g.norm42_project_markers = false
-- to ignore them.
local markers = { on = ".norm42", off = ".nonorm42" }

local function project_marker(path)
  if vim.g.norm42_project_markers == false or path == "" then
    return nil
  end

  local root = vim.fs.root(path, { markers.on, markers.off })
  if not root then
    return nil
  end
  -- Both markers in the same directory: forcing the norm wins.
  return vim.uv.fs_stat(root .. "/" .. markers.on) ~= nil
end

-- Order: `:Norm42` (per buffer), project marker, .clang-format (personal
-- style), then the 42 header.
function M.enabled(bufnr)
  bufnr = resolve(bufnr)
  if not vim.api.nvim_buf_is_valid(bufnr) or vim.bo[bufnr].filetype ~= "c" then
    return false
  end

  local override = vim.b[bufnr].norm42
  if override ~= nil then
    return override
  end

  local path = vim.api.nvim_buf_get_name(bufnr)
  local marked = project_marker(path)
  if marked ~= nil then
    return marked
  end

  if path ~= "" and vim.fs.root(path, { ".clang-format", "_clang-format" }) then
    return false
  end
  return M.has_header(bufnr)
end

-- Editor settings that follow the norm (colorcolumn, single-file build
-- flags). Set vim.g.norm42_adapt = false, or run :Norm42Adapt, to turn
-- them off.
function M.adapt_enabled()
  return vim.g.norm42_adapt ~= false
end

local colorcolumn = "81"

-- Only clears a colorcolumn this module set, never one chosen by hand.
function M.refresh_window(win)
  win = win or vim.api.nvim_get_current_win()
  if not vim.api.nvim_win_is_valid(win) then
    return
  end

  local bufnr = vim.api.nvim_win_get_buf(win)
  if M.adapt_enabled() and M.enabled(bufnr) then
    vim.api.nvim_set_option_value("colorcolumn", colorcolumn, { scope = "local", win = win })
    vim.w[win].norm42_colorcolumn = true
  elseif vim.w[win].norm42_colorcolumn then
    vim.api.nvim_set_option_value("colorcolumn", "", { scope = "local", win = win })
    vim.w[win].norm42_colorcolumn = nil
  end
end

function M.refresh_windows()
  for _, win in ipairs(vim.api.nvim_list_wins()) do
    M.refresh_window(win)
  end
end

-- Windows and norminette diagnostics, after the norm changed for buffers.
function M.refresh()
  M.refresh_windows()
  for _, bufnr in ipairs(vim.api.nvim_list_bufs()) do
    if vim.api.nvim_buf_is_loaded(bufnr) and vim.bo[bufnr].filetype == "c" then
      M.lint(bufnr)
    end
  end
end

function M.toggle(bufnr)
  bufnr = resolve(bufnr)
  vim.b[bufnr].norm42 = not M.enabled(bufnr)
  M.refresh()
  vim.notify("Norme 42 " .. (vim.b[bufnr].norm42 and "activée" or "désactivée") .. " pour ce buffer")
end

function M.toggle_adapt()
  vim.g.norm42_adapt = not M.adapt_enabled()
  M.refresh_windows()
  vim.notify("Réglages liés à la norme 42 " .. (M.adapt_enabled() and "activés" or "désactivés"))
end

-- `:Norm42Project on|off|clear` writes or removes the marker at the
-- project root (the buffer's directory when there is no project).
function M.set_project(state, bufnr)
  bufnr = resolve(bufnr)
  local path = vim.api.nvim_buf_get_name(bufnr)
  local root = require("vle-roux.c_tools").project_root(bufnr)
    or (path ~= "" and vim.fs.dirname(path))
    or vim.uv.cwd()

  for _, name in pairs(markers) do
    vim.fn.delete(root .. "/" .. name)
  end

  local message = "Marqueur norme 42 retiré de " .. root
  if state == "on" or state == "off" then
    local marker = root .. "/" .. markers[state]
    if vim.fn.writefile({}, marker) ~= 0 then
      vim.notify("Impossible d'écrire " .. marker, vim.log.levels.ERROR)
      return
    end
    message = "Norme 42 " .. (state == "on" and "forcée" or "désactivée") .. " pour " .. root
  end

  M.refresh()
  vim.notify(message)
end

-- norminette reports visual columns (tabs expanded to 4); diagnostics need bytes.
local function byte_column(text, visual_column)
  local column = 1
  for index = 1, #text do
    if column >= visual_column then
      return index
    end
    if text:sub(index, index) == "\t" then
      column = column + 4 - ((column - 1) % 4)
    else
      column = column + 1
    end
  end
  return #text + 1
end

local function parse_norminette(output, bufnr)
  local diagnostics = {}
  for line in vim.gsplit(output, "\n", { plain = true }) do
    line = line:gsub("\27%[[%d;]*m", "")
    local code, row, column, message = line:match("^Error: (%S+)%s+%(line:%s*(%d+), col:%s*(%d+)%):%s*(.-)%s*$")
    if code then
      row = tonumber(row)
      local text = vim.api.nvim_buf_get_lines(bufnr, row - 1, row, false)[1] or ""
      local col = byte_column(text, tonumber(column)) - 1
      table.insert(diagnostics, {
        lnum = row - 1,
        col = col,
        end_lnum = row - 1,
        end_col = col,
        code = code,
        message = message,
        severity = vim.diagnostic.severity.ERROR,
        source = "norminette",
      })
    end
  end
  return diagnostics
end

-- nvim-lint definition. norminette reads the file on disk, so it runs on
-- read and after each write.
function M.linter()
  return {
    cmd = "norminette",
    stdin = false,
    append_fname = true,
    args = {},
    stream = "stdout",
    ignore_exitcode = true,
    parser = parse_norminette,
  }
end

-- Lints norm files, and clears stale diagnostics from the others.
function M.lint(bufnr)
  bufnr = resolve(bufnr)
  local ok, lint = pcall(require, "lint")
  if not ok or not vim.api.nvim_buf_is_valid(bufnr) or vim.bo[bufnr].filetype ~= "c" then
    return
  end

  local path = vim.api.nvim_buf_get_name(bufnr)
  if M.enabled(bufnr) and vim.fn.executable("norminette") == 1 and vim.fn.filereadable(path) == 1 then
    vim.api.nvim_buf_call(bufnr, function()
      lint.try_lint("norminette")
    end)
  else
    vim.diagnostic.reset(lint.get_namespace("norminette"), bufnr)
  end
end

return M
